sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float angle;
uniform float2 center;
uniform float style;
uniform float alpha;
uniform float offset;
uniform float blend;

half4 main(float2 coord) {
    float theta = radians(angle);
    float2 d = float2(cos(theta), sin(theta));
    float2 normal = float2(-sin(theta), cos(theta));
    float2 c = center * size;
    float2 v = coord - c;
    if (style > 0.5) {
        half4 src = image.eval(coord);
        half4 copy = image.eval(c + reflect(v, normal) - normal * offset * dot(abs(normal), size));
        half a = half(max(alpha, 0.0));
        if (blend > 0.5) {
            half3 base = unpremul(src).rgb;
            half3 other = unpremul(copy).rgb;
            half3 mixed = blend < 1.5 ? base * other : base + other - base * other;
            return half4(clamp(mix(base, mixed, a), 0.0, 1.0) * src.a, src.a);
        }
        half4 o = copy * a + src * (1.0 - copy.a * a);
        half oa = clamp(o.a, 0.0, 1.0);
        return half4(clamp(o.rgb, 0.0, oa), oa);
    }
    float side = dot(v, normal);
    float2 sc = coord;
    if (side < 0.0) {
        sc = c + reflect(v, normal);
    }
    return image.eval(sc);
}
